// Shape of the official-result JSON files in public/data/results-*.json.
// Generated by scripts/parse-frankfurt-results.py and analogous scripts.

export interface ResultsCandidate {
  /** Ballot position within the party list — matches Candidate.position
   * in the data file, used as the join key. */
  position: number;
  lastName: string;
  firstName: string;
  profession?: string | null;
  /** Citywide Stimmen this candidate received. Null when no vote tally is
   * available (e.g. positions added to the roster after ballots were
   * printed, or candidates struck from a list before election day). */
  stimmen: number | null;
  /** Berlin: only elected members are listed, each flagged here. */
  elected?: boolean;
  /** AGH: how the seat was won — Direktmandat or Landes-/Bezirksliste. */
  via?: 'wahlkreis' | 'liste';
  /** AGH Direktmandat: Wahlkreis name, e.g. "Mitte 5". */
  wahlkreis?: string;
}

export interface ResultsParty {
  /** Liste-Nummer matching the data file's `Party.listNumber`. */
  listNumber: number;
  /** Short name, e.g. "CDU", "GRÜNE", "BFF". */
  shortName: string;
  /** Full party name. */
  fullName: string;
  /** Hex color from the Hessen parties.json metadata. */
  color: string | null;
  /** Vote share, percent. */
  percent: number | null;
  /** Absolute Stimmen for the party citywide (sum across its candidates). */
  votesAbsolute: number | null;
  /** Gewichtete Stimmen — Hessen's seat-allocation input. */
  votesWeighted: number | null;
  /** Change in vote share vs. the previous election, %-points. */
  percentChange?: number | null;
  /** Seats won. 0 if the party didn't make it in. */
  seats: number;
  /** MMP only: Wahlkreise won via Erststimme. */
  direktmandate?: number;
  /** MMP only: the party's Erststimmen (constituency) result. `percent` /
   * `votesAbsolute` above are the Zweitstimmen. */
  erststimmen?: {
    votesAbsolute: number | null;
    percent: number | null;
    percentChange: number | null;
  } | null;
  /** Every candidate on the party's ballot list — winners AND non-winners.
   * Ordered by ballot position. */
  candidates: ResultsCandidate[];
}

export interface ResultsTotals {
  validVotes: number | null;
  validBallots: number | null;
  /** Wahlberechtigte. */
  wahlberechtigte?: number | null;
  /** Wähler:innen total (= validBallots + ungueltigeStimmzettel). */
  waehlerGesamt?: number | null;
  /** Ungültige Stimmzettel count. */
  ungueltigeStimmzettel?: number | null;
  turnout: number | null;
  kandidatenInsgesamt: number | null;
  frauenInsgesamt: number | null;
  ballotsWithListenkreuz: number | null;
  ballotsWithListenkreuzPercent: number | null;
}

export interface ResultsWahlkreis {
  /** Official code, e.g. "0105". */
  id: string;
  name: string;
  bezirk: string;
  winner: { lastName: string; firstName: string; party: string };
}

export interface ResultsData {
  election: string;
  /** Date string of the data snapshot, e.g. "2026-03-27". */
  stand: string;
  /** Preliminary (election night) vs. final (Wahlausschuss) result.
   * Absent = treated as final. */
  status?: 'vorläufig' | 'endgültig';
  totalSeats: number;
  totals: ResultsTotals;
  parties: ResultsParty[];
  /** Optional left-to-right ideological ordering of party shortNames, used to
   * arrange seats on the hemicycle (Linke … AfD). Editorial — when absent,
   * consumers fall back to seat-count desc. */
  ideologicalOrder?: string[];
  /** MMP only: Direktmandat winner per Wahlkreis. */
  wahlkreise?: ResultsWahlkreis[];
  sources: string[];
}
